// ThreadPool: reuse existing threads (preferred)
ThreadPool.QueueUserWorkItem(_ =>
{
    DoBackgroundWork();
});

// New Thread: creates a dedicated OS thread every time
new Thread(() => DoBackgroundWork()).Start();

// Task.Run: schedules on the ThreadPool by default
Task.Run(() => DoBackgroundWork());

public string GetData()
{
    // Blocks a ThreadPool thread while the async operation runs
    return GetDataAsync().Result;
}

public async Task<string> GetDataAsync()
{
    var response = await _httpClient.GetAsync("https://api.example.com/data");
    return await response.Content.ReadAsStringAsync();
}
